// Original spreadsheet review and polished store workspace.
let bulkUploadGeneration=0,uploadedSheetState=null,uploadDatabasePromise=null;
function openUploadDatabase(){if(uploadDatabasePromise)return uploadDatabasePromise;uploadDatabasePromise=new Promise((resolve,reject)=>{if(!window.indexedDB){reject(Error('File storage is unavailable in this browser. Enable browser storage and retry.'));return}const request=window.indexedDB.open('power-electronics-upload-files',1);request.onupgradeneeded=()=>{if(!request.result.objectStoreNames.contains('uploads'))request.result.createObjectStore('uploads',{keyPath:'id'})};request.onsuccess=()=>{const db=request.result;db.onversionchange=()=>{db.close();uploadDatabasePromise=null};resolve(db)};request.onerror=()=>reject(Error('The uploaded file could not be stored.'));request.onblocked=()=>reject(Error('Close other demo tabs and retry the upload.'))}).catch(error=>{uploadDatabasePromise=null;throw error});return uploadDatabasePromise}
let uploadArchive={async put(record){const db=await openUploadDatabase();return new Promise((resolve,reject)=>{const tx=db.transaction('uploads','readwrite');tx.objectStore('uploads').put(record);tx.oncomplete=()=>resolve(record.id);tx.onerror=tx.onabort=()=>reject(Error('There is not enough browser storage to retain this spreadsheet.'))})},async get(id){const db=await openUploadDatabase();return new Promise((resolve,reject)=>{const request=db.transaction('uploads','readonly').objectStore('uploads').get(id);request.onsuccess=()=>resolve(request.result||null);request.onerror=()=>reject(Error('The original spreadsheet could not be opened.'))})},async delete(id){const db=await openUploadDatabase();return new Promise((resolve,reject)=>{const tx=db.transaction('uploads','readwrite');tx.objectStore('uploads').delete(id);tx.oncomplete=resolve;tx.onerror=tx.onabort=()=>reject(Error('Temporary file could not be removed.'))})}};
async function archiveSpreadsheet(file){const record={id:'upload-'+crypto.randomUUID(),name:file.name,type:file.type||'application/octet-stream',size:file.size,at:stamp(),blob:new Blob([await file.arrayBuffer()],{type:file.type||'application/octet-stream'})};await uploadArchive.put(record);return record}
loadBulkFile=async function(file){const generation=++bulkUploadGeneration,previousFileId=bulkDraft?.fileId;bulkDraft=null;const form=$('#bulkrequestform');const submit=$('#bulksubmit'),preview=$('#bulkpreview');submit.disabled=true;$('#bulkerror').textContent='';preview.innerHTML='<div class="upload-processing" role="status"><span class="loading-spinner"></span>Reading and checking your spreadsheet…</div>';let archived=null;try{if(previousFileId)try{await uploadArchive.delete(previousFileId)}catch{}if(generation!==bulkUploadGeneration)return;const wb=await workbookFromFile(file),sheet=wb.SheetNames.find(n=>n.toLowerCase()==='items')||wb.SheetNames[0],items=normalizeBulkRows(sheetMatrix(wb,sheet));if(generation!==bulkUploadGeneration)return;archived=await archiveSpreadsheet(file);if(generation!==bulkUploadGeneration||!form.isConnected||$('#bulkrequestform')!==form){await uploadArchive.delete(archived.id);return}bulkDraft={items,filename:file.name,fileId:archived.id,fileSize:file.size};preview.innerHTML=`<div class="uploaded-file-success"><span class="file-success-icon">${icon('box',22)}</span><div><b>${esc(file.name)}</b><small>${(file.size/1024).toFixed(1)} KB · ${items.length} items · ${items.reduce((a,i)=>a+i.count,0)} units</small></div><span class="workflow-pill request-available">Ready</span></div><div class="table-scroll bulk-preview-table"><table class="data-table"><thead><tr><th>Component</th><th>Quantity</th></tr></thead><tbody>${items.map(i=>`<tr><td>${esc(i.item)}</td><td>${i.count}</td></tr>`).join('')}</tbody></table></div><p class="upload-retention-note">Your original spreadsheet will be available to the admin with this request.</p>`;submit.disabled=false;return bulkDraft}catch(error){if(archived)try{await uploadArchive.delete(archived.id)}catch{}if(generation===bulkUploadGeneration){bulkDraft=null;preview.innerHTML='';submit.disabled=true;throw error}}};
function authorizedBulkOrder(id){const o=bulkOrders.find(o=>o.id===id);if(!o||!user||(user.role!=='admin'&&o.owner!==user.email))throw Error('This file is unavailable for this account.');return o}
async function originalCustomerUpload(id){const o=authorizedBulkOrder(id);if(!o.uploadedFileId)throw Error('The original file was not retained for this earlier request. The submitted item list is still available.');const record=await uploadArchive.get(o.uploadedFileId);authorizedBulkOrder(id);if(!record)throw Error('The original file is no longer in this browser. The submitted item list remains available.');if(record.id!==o.uploadedFileId)throw Error('File does not match this request.');return record}
function fileAttachmentPanel(o){return `<section class="customer-file-panel"><div class="file-attachment-icon">${icon('box',24)}</div><div class="file-attachment-meta"><span class="eyebrow">Customer spreadsheet</span><b>${esc(o.filename)}</b><small>${o.uploadedFileId?`${((o.uploadedFileSize||0)/1024).toFixed(1)} KB · Original file retained`:'Earlier request · Submitted rows available'}</small></div><div class="file-attachment-actions">${o.uploadedFileId?`<button type="button" class="btn btn-outline btn-small" data-refinement="preview-file" data-id="${o.id}">Preview spreadsheet</button><button type="button" class="btn btn-small" data-refinement="download-file" data-id="${o.id}">Download original</button>`:`<button type="button" class="btn btn-outline btn-small" data-refinement="download-items" data-id="${o.id}">Download submitted rows</button>`}</div><div id="customerfilepreview" class="customer-file-preview" hidden></div></section>`}
const refinedBulkDetail=bulkDetail;
bulkDetail=function(id){refinedBulkDetail(id);if(user?.role!=='admin')return;const o=authorizedBulkOrder(id);$('#modalcontent').innerHTML=$('#modalcontent').innerHTML.replace('<div class="section-head"><h3>Requested components</h3>',fileAttachmentPanel(o)+'<div class="section-head"><h3>Requested components</h3>')};
function workbookPreview(record,buffer,sheetName){const wb=XLSX.read(new Uint8Array(buffer),{type:'array',sheetRows:252,cellFormula:true});if(!wb.SheetNames.length)throw Error('No worksheet was found.');const name=sheetName&&wb.SheetNames.includes(sheetName)?sheetName:wb.SheetNames.find(n=>n.toLowerCase()==='items')||wb.SheetNames[0],matrix=XLSX.utils.sheet_to_json(wb.Sheets[name],{header:1,defval:'',blankrows:true,raw:false});return {record,wb,sheet:name,matrix,page:0}}
function sheetPreviewMarkup(state){const headers=state.matrix[0]||[],rows=state.matrix.slice(1),pages=Math.max(1,Math.ceil(rows.length/25)),slice=rows.slice(state.page*25,(state.page+1)*25),cols=Math.min(12,Math.max(headers.length,...slice.map(r=>r.length),1));return `<div class="sheet-preview-toolbar"><label>Worksheet<select data-refinement-sheet="true">${state.wb.SheetNames.map(n=>`<option ${n===state.sheet?'selected':''}>${esc(n)}</option>`).join('')}</select></label><span>${rows.length} rows · First 251 rows · Original worksheet preview</span><button type="button" class="filter-reset" data-refinement="close-file-preview">Close preview</button></div><div class="table-scroll"><table class="data-table original-sheet-table"><thead><tr><th>Row</th>${Array.from({length:cols},(_,i)=>`<th>${esc(headers[i]||'Column '+(i+1))}</th>`).join('')}</tr></thead><tbody>${slice.map((row,i)=>`<tr><td>${state.page*25+i+2}</td>${Array.from({length:cols},(_,c)=>`<td>${esc(String(row[c]??'').slice(0,300))}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="sheet-preview-pagination"><span>Page ${state.page+1} of ${pages} · Showing up to 12 columns; the download retains the complete file.</span><button type="button" class="btn btn-outline btn-small" data-refinement="sheet-page" data-page="${state.page-1}" ${state.page===0?'disabled':''}>Previous</button><button type="button" class="btn btn-outline btn-small" data-refinement="sheet-page" data-page="${state.page+1}" ${state.page+1>=pages?'disabled':''}>Next</button></div>`}
async function previewCustomerUpload(id){requireDemoAdmin();const container=$('#customerfilepreview');container.hidden=false;container.innerHTML='<div class="upload-processing"><span class="loading-spinner"></span>Opening the original spreadsheet…</div>';const record=await originalCustomerUpload(id),buffer=await record.blob.arrayBuffer();requireDemoAdmin();if(!container.isConnected)return;uploadedSheetState={...workbookPreview(record,buffer),orderId:id,buffer};container.innerHTML=sheetPreviewMarkup(uploadedSheetState)}
async function downloadCustomerUpload(id){requireDemoAdmin();const record=await originalCustomerUpload(id);requireDemoAdmin();const url=URL.createObjectURL(record.blob),a=document.createElement('a');a.href=url;a.download=record.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Original spreadsheet download started')}
const polishedCustomerBulkPage=customerBulkPage;
customerBulkPage=function(){let html=polishedCustomerBulkPage();html=html.replace('One spreadsheet. Your whole project.','Equip your next big idea.').replace('Send your component list and quantities. Our team will review it and prepare a quotation.','A simpler way to source components for your classroom or lab. Upload a list, share your delivery details and track your quotation.');html=html.replace('<div class="bulk-layout">','<div class="request-journey"><span><b>01</b> Share your details</span><i></i><span><b>02</b> Add your component list</span><i></i><span><b>03</b> Receive your quotation</span></div><div class="bulk-layout">');html=html.replace('<label class="field">Upload your item list<input id="bulkfile" type="file" accept=".xlsx,.xls,.csv" required></label>','<label class="bulk-file-control" for="bulkfile"><span class="bulk-file-icon">'+icon('box',28)+'</span><b>Choose your component spreadsheet</b><span>XLSX, XLS or CSV · Maximum 5 MB</span><input id="bulkfile" type="file" accept=".xlsx,.xls,.csv" aria-describedby="bulkfilehint bulkerror" required></label>');html=html.replace('<small>Up to 250 lines · 5 MB · Item and Count columns</small>','<small id="bulkfilehint">Up to 250 lines. Include Item and Count columns. Your file is retained for admin review.</small>');return html};
function adminSideNavigation(active){const nodes=[['Overview','/admin','box'],['Bulk orders','/admin/bulk-orders','truck'],['Stock requests','/admin/stock-requests','support'],['Pricing & stock','/admin/pricing','cart'],['Upload Excel','/admin/upload','box'],['Uploaded items','/admin/uploads','box'],['Price versions','/admin/price-history','box'],['Settings','/admin/settings','user'],['Notifications','/notifications','support']];return `<aside class="admin-workspace-nav"><div class="admin-nav-heading"><span class="logo-mark">ϟ</span><div><b>Power Electronics</b><small>Store workspace</small></div></div><span class="admin-nav-group">MANAGE YOUR STORE</span><nav aria-label="Store workspace">${nodes.map(([label,path,i])=>`<a href="#${path}" ${route().path===path?'aria-current="page"':''}>${icon(i,18)}<span>${label}</span>${path==='/admin/bulk-orders'&&bulkOrders.filter(o=>o.status==='Submitted').length?`<small>${bulkOrders.filter(o=>o.status==='Submitted').length}</small>`:''}</a>`).join('')}</nav><div class="admin-session"><span class="admin-avatar">A</span><div><b>Store administrator</b><small>Demo workspace</small></div></div></aside>`}
const polishedImportLayout=importLayout;
importLayout=function(content,active){if(user?.role!=='admin')return admin();return `<div class="admin-shell polished-admin"><div class="admin-workspace-grid">${adminSideNavigation(active)}<div class="admin-main-content"><div class="workspace-topbar"><div><span>WORKSPACE</span><b>${({bulk:'Bulk quotations',pricing:'Catalog pricing',upload:'Catalog import',items:'Imported products',history:'Price versions',settings:'Store settings',requests:'Stock requests',notifications:'Notifications'})[active]||'Store operations'}</b></div><a href="#/notifications">${bellIcon()}<span>${visibleNotifications().filter(n=>!notificationRead(n)).length} unread updates</span></a></div>${content}</div></div></div>`};
const workspaceAdmin=admin;
admin=function(){let html=workspaceAdmin();if(user?.role!=='admin')return html;html=html.replace("Welcome back, Alex. Here's how your demo store is doing.",'Review requests, manage fulfillment and keep your catalog up to date.').replace('<div class="saved-note">Demo workspace · All edits and orders are stored in this browser. This preview is not a secure production admin system.</div>','');const body=html.replace(/^<div class="admin-shell"><div class="wrap">/,'').replace(/<\/div><\/div>$/,'');return importLayout(body,'overview')};
document.addEventListener('click',async e=>{const b=e.target.closest('[data-refinement]');if(!b)return;const action=b.dataset.refinement;try{if(action==='preview-file'){b.disabled=true;try{await previewCustomerUpload(b.dataset.id)}finally{b.disabled=false}}else if(action==='download-file')await downloadCustomerUpload(b.dataset.id);else if(action==='download-items'){requireDemoAdmin();const o=authorizedBulkOrder(b.dataset.id);downloadCsv(o.id+'-submitted-items.csv',[['Item','Count'],...o.items.map(i=>[i.item,i.count])])}else if(action==='close-file-preview')$('#customerfilepreview').hidden=true;else if(action==='sheet-page'){requireDemoAdmin();authorizedBulkOrder(uploadedSheetState.orderId);uploadedSheetState.page=Math.max(0,Math.min(Math.ceil((uploadedSheetState.matrix.length-1)/25)-1,Number(b.dataset.page)));$('#customerfilepreview').innerHTML=sheetPreviewMarkup(uploadedSheetState)}}catch(error){if(action==='preview-file'&&$('#customerfilepreview'))$('#customerfilepreview').innerHTML=`<div class="error" role="alert">${esc(error.message)}</div>`;toast(error.message)}});
document.addEventListener('change',e=>{if(e.target.dataset.refinementSheet){requireDemoAdmin();const s=uploadedSheetState;authorizedBulkOrder(s.orderId);uploadedSheetState={...workbookPreview(s.record,s.buffer,e.target.value),orderId:s.orderId,buffer:s.buffer};$('#customerfilepreview').innerHTML=sheetPreviewMarkup(uploadedSheetState)}});
$('#modal').addEventListener('close',()=>{uploadedSheetState=null});
const deliveryCheckout=checkout;
checkout=function(){let html=deliveryCheckout();if(!cart.length)return html;return html.replace('<h3>Delivery information</h3>',`<h3>Delivery information</h3><div class="address-helper checkout-address-helper"><div><b>Find your address with Google <small title="Optional">(op)</small></b><span>Search your location, then confirm the delivery details below.</span></div><button type="button" class="btn btn-outline btn-small" data-experience="google-address" data-address-context="checkout">Search address</button></div><div id="checkoutgooglehost"></div><p id="checkoutgooglestatus" class="subtle" role="status">Search for an address or enter your delivery information below.</p>`) };
function isAdminWorkspaceRoute(path){return path==='/admin'||path.startsWith('/admin/')||path==='/notifications'}
function applyRoleShell(){const adminSession=user?.role==='admin';for(const selector of ['#storefrontheader','#storefrontfooter','#storeannouncement']){const node=$(selector);if(node)node.hidden=adminSession}for(const selector of ['#adminportalheader','#adminportalfooter']){const node=$(selector);if(node)node.hidden=!adminSession}if(adminSession){$('#adminunreadcount').textContent=visibleNotifications().filter(n=>!notificationRead(n)).length;$('#adminworkspacestatus').textContent='Workspace updated '+new Date().toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'})}}
const roleAwareHeader=updateHeader;
updateHeader=function(){roleAwareHeader();applyRoleShell()};
const roleAwareRender=render;
render=function(){if(user?.role==='admin'&&!isAdminWorkspaceRoute(route().path)){closeModal();location.hash='#/admin'}roleAwareRender();applyRoleShell()};
render();
